    for l in open(f):
        o=json.loads(l); c=(o.get('message') or {}).get('content')
        for b in c if isinstance(c,list) else []: yield b
f='evals/github-actions-security/results/raw/2026-11-26/gas-07-agent-workflow/with-skill/run-2/run.jsonl'
