    s=json.dumps(b.get('input') or b.get('content') or b.get('text'))
    for m in re.finditer(r'sim\.py|scratchpad',s): print('HIT',b.get('type'),s[max(0,m.start()-300):m.end()+200]); break
# every run: absolute write targets outside the workspace
hits=collections.defaultdict(set)
for f in glob.glob('evals/*/results/raw/2026-11-2*/*/*/run-*/run.jsonl'):
    for b in blocks(f):
        if b.get('type')!='tool_use': continue
        i=b.get('input') or {}
        if b['name'] in('Write','Edit'):
            p=i.get('file_path','')
            if '/workspace' not in p: hits[f].add(b['name']+' '+p)
        elif b['name']=='Bash':
            for p in re.findall(r'(?:>>?\s*|\bcd |\btee |mktemp [^;\n]*)(["\']?(?:/|\$TMPDIR|~|\$HOME)[^\s;"\'|&)]*)',i.get('command','')):
                if '/workspace' not in p and p!='/dev/null': hits[f].add('Bash '+p)
for f,v in sorted(hits.items()): print(f.replace('evals/','').replace('/run.jsonl',''),sorted(v)[:6])
